adius:50%;box-shadow:0 0 8px #ff477d;margin-right:6px}.controls-hint{display:flex;align-items:center;gap:8px;color:#aab1c4;font-weight:600}.controls-hint kbd{padding:3px 5px;color:#fff;border:1px solid #ffffff3d;border-radius:3px;background:#ffffff0c;font:700 9px 'Rajdhani'}.pause-badge{position:absolute;z-index:5;right:16px;top:50%;transform:translateY(-50%);font-size:18px;color:#fff8;cursor:pointer;padding:9px}.mobile-controls{display:none}.mobile-controls button{touch-action:none;user-select:none;-webkit-user-select:none}.mobile-controls button:active,.mobile-controls button.pressed{filter:brightness(1.7);transform:scale(.94)}@keyframes pop{from{transform:scale(.5);opacity:0}to{transform:scale(1);opacity:1}}
