(() => {
  const canvas = document.querySelector('#arena'), ctx = canvas.getContext('2d');
  const ui = { playerHealth: document.querySelector('#playerHealth'), enemyHealth: document.querySelector('#enemyHealth'), playerEnergy: document.querySelector('#playerEnergy'), enemyEnergy: document.querySelector('#enemyEnergy'), timer: document.querySelector('#timer'), message: document.querySelector('#centerMessage'), title: document.querySelector('#centerMessage h1'), eyebrow: document.querySelector('.eyebrow'), sub: document.querySelector('.center-message p'), start: document.querySelector('#startBtn'), combo: document.querySelector('#combo'), comboCount: document.querySelector('#comboCount'), toast: document.querySelector('#toast'), status: document.querySelector('#statusText'), round: document.querySelector('#roundNumber') };
  let W=0,H=0,dpr=1,now=0,last=0,mode='intro',paused=false,muted=false,seconds=99,secTick=0,combo=0,comboClock=0,lastToast=0,shake=0,roundsWon=0;
  const keys = new Set(), held = new Set(), particles = [], rings = [];
  const player = makeFighter('player'), enemy = makeFighter('enemy');
  function makeFighter(side){return {side,x:side==='player'?.33:.67,y:.69,hp:100,energy:35,face:side==='player'?1:-1,attack:0,attackType:'',cool:0,stun:0,guard:false,dash:0,pose:0,walk:0,hitFlash:0,aiWait:.3,air:0,knock:0}}
  function resize(){dpr=Math.min(devicePixelRatio||1,2);W=innerWidth;H=innerHeight;canvas.width=Math.floor(W*dpr);canvas.height=Math.floor(H*dpr);ctx.setTransform(dpr,0,0,dpr,0,0)} addEventListener('resize',resize);resize();
  function rand(a,b){return a+Math.random()*(b-a)}
  function sound(freq=180,duration=.08,type='sawtooth',vol=.035){if(muted)return;try{const AC=window.AudioContext||window.webkitAudioContext;if(!window.ac)window.ac=new AC();let a=window.ac,o=a.createOscillator(),g=a.createGain();o.type=type;o.frequency.setValueAtTime(freq,a.currentTime);o.frequency.exponentialRampToValueAtTime(Math.max(35,freq*.55),a.currentTime+duration);g.gain.setValueAtTime(vol,a.currentTime);g.gain.exponentialRampToValueAtTime(.001,a.currentTime+duration);o.connect(g);g.connect(a.destination);o.start();o.stop(a.currentTime+duration)}catch{}}
  function toast(t){ui.toast.textContent=t;ui.toast.classList.add('show');lastToast=now}
  function burst(x,y,color,n=12,power=5){for(let i=0;i<n;i++){let a=rand(0,Math.PI*2),s=rand(1,power);particles.push({x,y,vx:Math.cos(a)*s,vy:Math.sin(a)*s,life:rand(.25,.65),max:.65,size:rand(2,5),color,grav:rand(0,90)})}}
  function ring(x,y,color){rings.push({x,y,r:8,life:.34,max:.34,color})}
  function activate(){if(mode==='fight')return; if(mode==='result'){player.hp=100;enemy.hp=100;player.energy=35;enemy.energy=35;seconds=99;combo=0;ui.round.textContent=String(roundsWon+1).padStart(2,'0')} mode='fight';paused=false;ui.message.classList.add('hidden');ui.status.textContent='DEFEAT KAITO TO CLAIM THE RIFT';toast('FIGHT!');sound(440,.16,'triangle',.05);}
  ui.start.addEventListener('click',activate);
  function endGame(won){mode='result';roundsWon=won?roundsWon+1:roundsWon;ui.title.textContent=won?'VICTORY':'DEFEATED';ui.eyebrow.textContent=won?'THE RIFT ANSWERS TO YOU':'THE VOID CLAIMS ANOTHER';ui.sub.textContent=won?'CHAMPION OF THE LAST SUN':'RISE AGAIN, WARRIOR';ui.start.innerHTML=won?'FIGHT AGAIN <span>↗</span>':'RETRY MATCH <span>↗</span>';ui.message.classList.remove('hidden');ui.message.classList.add('result');ui.status.textContent=won?'MATCH WON — THE ARENA IS YOURS':'MATCH LOST — RETRY THE CHALLENGE';if(won){roundsWon=Math.min(roundsWon,2);document.querySelectorAll('.round-dots i')[roundsWon-1]?.classList.add('won')}sound(won?590:110,.6,'triangle',.055)}
  function attack(f,type){if(mode!=='fight'||paused||f.stun>0||f.attack>0||f.cool>0)return;if(type==='special'&&f.energy<35){toast('NOT ENOUGH SPIRIT');return}if(type==='special')f.energy-=35;f.guard=false;f.attackType=type;f.attack=type==='light'?.25:type==='heavy'?.47:.62;f.cool=type==='light'?.3:type==='heavy'?.58:.78;f.pose=1;f.dash=0;const spec=type==='special';sound(spec?120: type==='heavy'?95:230,spec?.25:.12,spec?'sawtooth':'triangle',spec?.06:.035);if(spec){let dir=f.face;for(let i=0;i<18;i++)particles.push({x:f.x*W+dir*28,y:f.y*H-64,vx:dir*rand(150,390),vy:rand(-100,90),life:rand(.25,.55),max:.55,size:rand(4,12),color:f.side==='player'?'#65f7ff':'#ff5386',grav:0,bolt:true});ring(f.x*W+dir*100,f.y*H-60,f.side==='player'?'#63edff':'#ff477d')}}
  function hit(attacker,defender,type){if(defender.hp<=0)return;let dist=Math.abs(attacker.x-defender.x);if(dist>.205)return;let isPlayer=attacker===player,damage=type==='light'?7:type==='heavy'?13:21;let guarded=defender.guard&&defender.face===(defender.x>attacker.x?-1:1);if(guarded)damage=Math.max(2,Math.round(damage*.16));defender.hp=Math.max(0,defender.hp-damage);defender.hitFlash=.18;defender.stun=guarded?.12:type==='heavy'?.35:.23;defender.knock=guarded?.015:type==='special'?.12:type==='heavy'?.06:.025;shake=guarded?3:type==='special'?11:6;burst(defender.x*W,defender.y*H-55,guarded?'#b9edff':isPlayer?'#ff7598':'#82faff',guarded?6:14,guarded?3:7);ring(defender.x*W,defender.y*H-55,guarded?'#d9f9ff':isPlayer?'#ff477d':'#62f0ff');if(isPlayer){player.energy=Math.min(100,player.energy+(type==='special'?2:8));combo++;comboClock=2.2;ui.comboCount.textContent=combo;ui.combo.classList.add('active');if(combo===3)toast('3 HIT COMBO!');if(combo===5)toast('UNSTOPPABLE!')}else enemy.energy=Math.min(100,enemy.energy+8);sound(guarded?320:type==='heavy'?90:145,.12,guarded?'triangle':'square',guarded?.025:.05);if(defender.hp<=0){setTimeout(()=>{if(mode==='fight')endGame(isPlayer)},420)}}
  function attackWindow(f,dt){if(f.attack<=0)return;let before=f.attack;f.attack=Math.max(0,f.attack-dt);let active=f.attackType==='light'?(f.attack<.18&&before>=.18):f.attackType==='heavy'?(f.attack<.3&&before>=.3):(f.attack<.4&&before>=.4);if(active){if(f.attackType==='special'){if(Math.abs(f.x-(f===player?enemy:player).x)<.48)hit(f,f===player?enemy:player,'special')}else hit(f,f===player?enemy:player,f.attackType)}}
  function update(dt){now+=dt;if(mode!=='fight'||paused){updateFX(dt);return}secTick+=dt;if(secTick>=1){secTick--;seconds=Math.max(0,seconds-1);ui.timer.textContent=String(seconds).padStart(2,'0');if(seconds===0){endGame(player.hp>=enemy.hp);return}}if(comboClock>0){comboClock-=dt;if(comboClock<=0){combo=0;ui.combo.classList.remove('active')}}if(now-lastToast>1.3)ui.toast.classList.remove('show');
    const pMove=(keys.has('a')?-1:0)+(keys.has('d')?1:0), pDepth=(keys.has('w')?-1:0)+(keys.has('s')?1:0);player.guard=keys.has(' ')||held.has('block');if(player.stun<=0&&player.dash<=0){if(player.guard){player.walk=0}else if(pMove||pDepth){player.x+=pMove*dt*.56;player.y+=pDepth*dt*.22;player.walk+=dt*12}}if(player.dash>0){player.x+=player.face*dt*1.25;player.dash-=dt}player.x=Math.max(.12,Math.min(.88,player.x));player.y=Math.max(.53,Math.min(.78,player.y));
    enemy.face=enemy.x>player.x?-1:1;player.face=player.x>enemy.x?-1:1;
    enemy.aiWait-=dt;let gap=Math.abs(enemy.x-player.x);enemy.guard=false;if(enemy.stun<=0&&enemy.dash<=0){if(gap>.19){enemy.x+=enemy.face*dt*(gap>.42?.28:.12);enemy.y+=(player.y-enemy.y)*dt*.5;enemy.walk+=dt*9}else if(enemy.aiWait<=0){if(player.attack>0&&Math.random()<.42){enemy.guard=true;enemy.aiWait=rand(.3,.55)}else{attack(enemy,enemy.energy>=35&&Math.random()<.24?'special':Math.random()<.28?'heavy':'light');enemy.aiWait=rand(.5,.95)}}}if(enemy.dash>0){enemy.x+=enemy.face*dt*.7;enemy.dash-=dt}enemy.x=Math.max(.12,Math.min(.88,enemy.x));
    for(const f of [player,enemy]){f.cool=Math.max(0,f.cool-dt);f.stun=Math.max(0,f.stun-dt);f.hitFlash=Math.max(0,f.hitFlash-dt);f.attack=Math.max(0,f.attack);if(f.knock){f.x+= (f===player?-1:1)*f.knock*dt*3;f.knock=Math.max(0,f.knock-dt*.3)}if(f.energy<0)f.energy=0;}
    attackWindow(player,dt);attackWindow(enemy,dt);ui.playerHealth.style.width=player.hp+'%';ui.enemyHealth.style.width=enemy.hp+'%';ui.playerEnergy.style.width=player.energy+'%';ui.enemyEnergy.style.width=enemy.energy+'%';updateFX(dt)
  }
  function updateFX(dt){for(let i=particles.length-1;i>=0;i--){let p=particles[i];p.life-=dt;p.x+=p.vx*dt;p.y+=p.vy*dt;p.vy+=p.grav*dt;if(p.life<=0)particles.splice(i,1)}for(let i=rings.length-1;i>=0;i--){rings[i].r+=dt*280;rings[i].life-=dt;if(rings[i].life<=0)rings.splice(i,1)}shake=Math.max(0,shake-dt*20)}
  function polygon(points,fill,stroke,lw=1){ctx.beginPath();points.forEach((p,i)=>i?ctx.lineTo(p[0],p[1]):ctx.moveTo(p[0],p[1]));ctx.closePath();if(fill){ctx.fillStyle=fill;ctx.fill()}if(stroke){ctx.strokeStyle=stroke;ctx.lineWidth=lw;ctx.stroke()}}
  function bg(){let sky=ctx.createLinearGradient(0,0,0,H);sky.addColorStop(0,'#11152b');sky.addColorStop(.48,'#292044');sky.addColorStop(.7,'#402340');sky.addColorStop(1,'#111222');ctx.fillStyle=sky;ctx.fillRect(0,0,W,H);
    // distant moon and atmospheric halo
    let cx=W*.5,cy=H*.34,rad=Math.min(W,H)*.17;let halo=ctx.createRadialGradient(cx,cy,rad*.15,cx,cy,rad*2.7);halo.addColorStop(0,'#f8bcce30');halo.addColorStop(.35,'#d75c9850');halo.addColorStop(1,'transparent');ctx.fillStyle=halo;ctx.fillRect(0,0,W,H*.75);ctx.beginPath();ctx.arc(cx,cy,rad,0,Math.PI*2);let moon=ctx.createLinearGradient(cx-rad,cy-rad,cx+rad,cy+rad);moon.addColorStop(0,'#ffe9de');moon.addColorStop(.55,'#d59bab');moon.addColorStop(1,'#73567e');ctx.fillStyle=moon;ctx.shadowColor='#ff6caa';ctx.shadowBlur=44;ctx.fill();ctx.shadowBlur=0;
    // mountain silhouettes
    polygon([[0,H*.52],[0,H*.42],[W*.08,H*.34],[W*.16,H*.43],[W*.26,H*.36],[W*.36,H*.48],[W*.51,H*.38],[W*.62,H*.46],[W*.76,H*.34],[W*.88,H*.45],[W,H*.37],[W,H*.55]],'#17162c');polygon([[0,H*.56],[W*.11,H*.45],[W*.24,H*.53],[W*.38,H*.42],[W*.49,H*.52],[W*.63,H*.43],[W*.78,H*.52],[W*.91,H*.4],[W,H*.48],[W,H*.62]],'#211a32');
    // temple silhouette
    const ty=H*.47;ctx.fillStyle='#141527';ctx.fillRect(W*.08,ty,W*.13,H*.14);polygon([[W*.05,ty],[W*.145,ty-H*.075],[W*.24,ty]],'#121426');ctx.fillRect(W*.11,ty-H*.06,W*.07,H*.075);polygon([[W*.09,ty-H*.06],[W*.145,ty-H*.11],[W*.20,ty-H*.06]],'#141527');ctx.fillRect(W*.82,ty,W*.12,H*.12);polygon([[W*.79,ty],[W*.88,ty-H*.08],[W*.97,ty]],'#141527');
    // vertical lanterns
    for(let i=0;i<8;i++){let x=W*(.06+i*.125),y=H*(.43+Math.sin(i*3)*.035);ctx.fillStyle='#fd779533';ctx.fillRect(x,y,2,H*.12);ctx.fillStyle='#ffca8c';ctx.shadowBlur=12;ctx.shadowColor='#ff8766';ctx.fillRect(x-2,y+5,6,9);ctx.shadowBlur=0}
    floor();
  }
